const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const walvisBay = ee.Geometry.Point([14.5053, -22.9576]).buffer(10000); // 10km buffer around Walvis Bay
  const feb2021 = ['2021-02-01', '2021-02-28'];
  const febHistorical = ['2010-02-01', '2020-02-28']; // All Februarys from 2010-2020

  // Function to calculate NDVI and mask clouds
  function processS2(image) {
    // Cloud masking
    const qa = image.select('QA60');
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
                 .and(qa.bitwiseAnd(cirrusBitMask).eq(0));

    // Calculate NDVI
    const ndvi = image.normalizedDifference(['B8', 'B4']).rename('NDVI');
    return image.addBands(ndvi).updateMask(mask);
  }

  // 2. Data Acquisition for 2021
  let col2021 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(walvisBay)
    .filterDate(feb2021[0], feb2021[1])
    .map(processS2)
    .select('NDVI');

  // 3. Data Acquisition for historical period
  let colHistorical = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(walvisBay)
    .filterDate(febHistorical[0], febHistorical[1])
    .filter(ee.Filter.calendarRange(2, 2, 'month')) // Only February months
    .map(processS2)
    .select('NDVI');

  // Check collection sizes
  const size2021 = col2021.size().getInfo();
  const sizeHistorical = colHistorical.size().getInfo();

  console.log(`2021 Images: ${size2021}`);
  console.log(`Historical Images (2010-2020 Feb): ${sizeHistorical}`);

  // Handle empty collections
  if (size2021 === 0 || sizeHistorical === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // Calculate mean NDVI for 2021
  const mean2021 = col2021.mean();
  const stats2021 = mean2021.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: walvisBay,
    scale: 1000,
    maxPixels: 1e9
  });

  // Calculate mean NDVI for historical period
  const meanHistorical = colHistorical.mean();
  const statsHistorical = meanHistorical.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: walvisBay,
    scale: 1000,
    maxPixels: 1e9
  });

  const ndvi2021 = stats2021.get('NDVI_mean').getInfo();
  const count2021 = stats2021.get('NDVI_count').getInfo();
  const ndviHistorical = statsHistorical.get('NDVI_mean').getInfo();
  const countHistorical = statsHistorical.get('NDVI_count').getInfo();

  console.log(`2021 NDVI: ${ndvi2021?.toFixed(4)}, Pixels: ${count2021}`);
  console.log(`Historical NDVI: ${ndviHistorical?.toFixed(4)}, Pixels: ${countHistorical}`);

  // Check for valid pixels
  if (count2021 === 0 || countHistorical === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // Check for calculation failures
  if (ndvi2021 === null || ndviHistorical === null || 
      isNaN(ndvi2021) || isNaN(ndviHistorical) ||
      ndvi2021 > 1 || ndvi2021 < -1 || 
      ndviHistorical > 1 || ndviHistorical < -1) {
    console.log("<answer>C3</answer>");
    return;
  }

  // Compare and output result
  if (ndvi2021 > ndviHistorical) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
